int ati_remote_wonder2_probe(struct usb_interface *interface, const struct usb_device_id *id)
{
    struct usb_device *udev = interface_to_usbdev(interface);
    struct usb_host_interface *alt = &interface->cur_altsetting;
    struct usb_endpoint_descriptor *ep;
    struct ati_dev *dev;
    int i, rc;

    if (alt->desc.bNumEndpoints < 2)
        return -ENODEV;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    dev->interface = interface;
    dev->udev = udev;
    usb_set_intfdata(interface, dev);

    for (i = 0; i < alt->desc.bNumEndpoints; i++) {
        ep = &alt->endpoint[i].desc;
        if (usb_endpoint_is_bulk_in(ep))
            dev->ep_in = ep;
        else if (usb_endpoint_is_bulk_out(ep))
            dev->ep_out = ep;
    }

    if (!dev->ep_in || !dev->ep_out) {
        rc = -ENODEV;
        goto err_free_dev;
    }

    rc = usb_set_interface(udev, alt->desc.bInterfaceNumber, 1);
    if (rc < 0)
        goto err_free_dev;

    rc = ati_dev_init_urbs(dev);
    if (rc < 0)
        goto err_free_dev;

    rc = ati_dev_setup(dev);
    if (rc < 0)
        goto err_free_urbs;

    rc = sysfs_create_group(&dev->dev->kobj, &ati_dev_attr_group);
    if (rc < 0)
        goto err_teardown;

    return 0;

err_teardown:
    ati_dev_teardown(dev);
err_free_urbs:
    ati_dev_free_urbs(dev);
err_free_dev:
    kfree(dev);
    return rc;
}

int ati_probe(struct usb_interface *interface, const struct usb_device_id *id)
{
    struct usb_device *udev = usb_get_dev(interface_to_usbdev(interface));
    struct usb_host_endpoint *ep;
    struct urb *urb;
    struct ati_device *dev;
    int ret = -ENOMEM;

    if (interface->cur_altsetting->desc.bInterfaceNumber != 0)
        return -ENODEV;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    dev->udev = udev;
    dev->interface = interface;

    ep = usb_find_int_in_endpoint(interface->cur_altsetting);
    if (!ep)
        goto error;

    dev->int_in_endpoint = ep;

    urb = usb_alloc_urb(0, GFP_KERNEL);
    if (!urb)
        goto error;

    dev->urb = urb;

    usb_fill_int_urb(urb, udev, usb_rcvintpipe(udev, ep->desc.bEndpointAddress),
                     dev->interrupt, sizeof(dev->interrupt), ati_irq, dev,
                     ep->desc.bInterval);

    ret = usb_register_dev(interface, &ati_class);
    if (ret)
        goto error;

    ret = sysfs_create_group(&interface->dev.kobj, &ati_attr_group);
    if (ret)
        goto error_unregister;

    usb_set_intfdata(interface, dev);
    device_init_wakeup(&interface->dev, 1);

    return 0;

error_unregister:
    usb_deregister_dev(interface, &ati_class);
error:
    kfree(dev);
    return ret;
}

int ati_probe(struct usb_interface *interface, const struct usb_device_id *id)
{
    struct usb_device *dev = interface_to_usbdev(interface);
    struct ati_dev *ati;
    int rc = -ENOMEM;

    if (interface->cur_altsetting->desc.bInterfaceNumber != 0)
        return -ENODEV;

    ati = kzalloc(sizeof(*ati), GFP_KERNEL);
    if (!ati)
        return -ENOMEM;

    ati->udev = usb_get_dev(dev);
    ati->interface = interface;

    if (dev->actconfig->interface[1].altsetting[0].desc.bNumEndpoints < 1)
        goto error;

    rc = usb_set_interface(dev, 1, 0);
    if (rc < 0)
        goto error;

    usb_fill_int_urb(&ati->urb, dev, USB_DIR_IN | USB_TYPE_CLASS | USB_RECIP_INTERFACE,
                     ati->buffer, 8, ati_interrupt, ati, 100);

    rc = sysfs_create_group(&interface->dev.kobj, &ati_attr_group);
    if (rc)
        goto error;

    usb_set_intfdata(interface, ati);
    dev_info(&dev->dev, "ATI Remote Wonder II initialized\n");

    return 0;

error:
    if (ati->udev)
        usb_put_dev(ati->udev);
    kfree(ati);
    return rc;
}

int ati_remote_wonder_probe(struct usb_interface *interface, const struct usb_device_id *id)
{
    struct usb_device *udev = interface_to_usbdev(interface);
    struct ati_remote_dev *dev;
    int retval = -ENOMEM;

    /* Check interface number */
    if (interface->cur_altsetting->desc.bInterfaceNumber != 0)
        return -ENODEV;

    /* Allocate memory for our device state */
    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    dev->udev = usb_get_dev(udev);
    dev->interface = interface;

    /* Check for required endpoints and interfaces */
    if (interface->cur_altsetting->desc.bNumEndpoints != 2) {
        dev_err(&udev->dev, "invalid number of endpoints\n");
        goto error;
    }

    /* Claim the second interface (index 1) */
    if (usb_driver_claim_interface(&ati_remote_driver, interface, dev)) {
        dev_err(&udev->dev, "unable to claim interface\n");
        goto error;
    }

    /* Initialize URB and other device setup */
    if (ati_remote_init_urb(dev)) {
        dev_err(&udev->dev, "failed to initialize URB\n");
        goto error;
    }

    /* Create sysfs group for attributes */
    if (sysfs_create_group(&dev->dev->kobj, &ati_remote_attr_group)) {
        dev_err(&udev->dev, "failed to create sysfs group\n");
        goto error;
    }

    /* Everything was successfully initialized */
    usb_set_intfdata(interface, dev);
    return 0;

error:
    kfree(dev);
    return retval;
}

int ati_probe(struct usb_interface *interface, const struct usb_device_id *id)
{
    struct usb_device *udev = interface_to_usbdev(interface);
    struct ati_dev *dev;
    int retval = -ENOMEM;

    if (interface->cur_altsetting->desc.bInterfaceNumber != 0)
        return -ENODEV;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    dev->udev = udev;
    dev->interface = interface;

    if (interface->cur_altsetting->desc.bNumEndpoints < 1)
        goto error;

    dev->ep = &interface->cur_altsetting->endpoint[0];

    usb_set_intfdata(interface, dev);

    if (usb_driver_claim_interface(&ati_driver, interface, dev))
        goto error;

    dev->urb = usb_alloc_urb(0, GFP_KERNEL);
    if (!dev->urb)
        goto error;

    dev->urb->transfer_buffer = kmalloc(64, GFP_KERNEL);
    if (!dev->urb->transfer_buffer)
        goto error;

    dev->urb->transfer_flags = URB_NO_TRANSFER_DMA_MAP;
    dev->urb->pipe = usb_rcvintpipe(udev, dev->ep->desc.bEndpointAddress);
    dev->urb->transfer_buffer_length = 64;
    dev->urb->complete = ati_irq;

    if (sysfs_create_group(&interface->dev.kobj, &ati_attr_group))
        goto error;

    return 0;

error:
    if (dev->urb) {
        usb_free_urb(dev->urb);
    }
    kfree(dev);
    return retval;
}
